void bubble_sort(int* a, size_t n) {
    if (a == nullptr || n < 2) return;
    for (size_t i = 0; i + 1 < n; ++i) {
        bool swapped = false;
        for (size_t j = 0; j + 1 < n - i; ++j) {
            if (a[j] > a[j + 1]) {
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
                swapped = true;
            }
        }
        if (!swapped) break; // already sorted
    }
}

namespace {
void merge_sort_rec(int* a, size_t lo, size_t hi) {
    if (hi - lo < 2) return;
    size_t mid = lo + (hi - lo) / 2;
    merge_sort_rec(a, lo, mid);
    merge_sort_rec(a, mid, hi);

    // Copy both halves to a temporary buffer.
    int* tmp = new int[hi - lo];
    size_t i = 0;
    for (size_t k = lo; k < hi; ++k) tmp[i++] = a[k];

    // Merge back into a[lo, hi).
    size_t p = 0;
    for (size_t k = lo; k < hi; ++k) {
        bool take_left;
        if (p + mid - lo >= i) {
            take_left = false; // left exhausted
        } else if (p + hi - mid >= i) {
            take_left = true;  // right exhausted
        } else {
            take_left = tmp[p + (mid - lo)] <= tmp[p + (hi - mid)];
        }
        a[k] = take_left ? tmp[p + (mid - lo)] : tmp[p + (hi - mid)];
        ++p;
    }
    delete[] tmp;
}
