    // Build undirected adjacency list.
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e.first, v = e.second;
        if (u < 0 || u >= n || v < 0 || v >= n) continue; // ignore out-of-range endpoints
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::queue<int> q;
    dist[source] = 0;
    q.push(source);
