public:
  std::mutex m;
  std::condition_variable cv;
  bool ready = false;
};

void wait_ready(Server& s) {
  std::unique_lock<std::mutex> lock(s.m);
  s.cv.wait(lock, [&]{ return s.ready; });   // blocks until notified
}
